    // ----------------------------
    public function doFollowup()
    {

        echo "<script>top.writeProgress('MEMULAI PROSES FOLLOWUP....');</script>";
        $starttime = microtime(true);
        if ($this->transaksiMaintenance === true) {
            $msg = $this->transaksiMaintenanceMsg['title'] . "<br>" . $this->transaksiMaintenanceMsg['mesage'];
            mati_disini($msg);
        }

        $transaksiID_reference = $no = rtrim($this->uri->segment(5), "-");

        // 1. Validasi Indikasi Transaksi Ganda (Session Check) - Early Validation Pattern
        if (isset($_SESSION['is_processing_followup_'.$no]) && $_SESSION['is_processing_followup_'.$no] === true) {
            die("Transaksi sedang diproses. Mohon tunggu dan jangan klik tombol simpan dua kali.");
        }
        $_SESSION['is_processing_followup_'.$no] = true;

        $stepNum = $this->uri->segment(6);
        $stepNumCurrent = $this->uri->segment(7);

        if ($stepNum > 2) {
            if ($this->transaksiMaintenanceStock === true) {
                $msg = $this->transaksiMaintenanceMsgStock['title'] . "<br>" . $this->transaksiMaintenanceMsgStock['mesage'];
                mati_disini($msg);
            }
        }

        // region mengunci transaksi by $no dan userID (Early Validation / Fail-Fast Pattern)
        if (isset($this->session->login['ghost']) && $this->session->login['ghost'] == 0) {
            $this->load->model("Mdls/MdlLockerTransaksi");
            $lt = New MdlLockerTransaksi();
            $lt->addFilter("transaksi_id='$no'");
            $ltTmp = $lt->lookupAll()->result();
            if (sizeof($ltTmp) > 0) {
                $byUpdateHold = array();
                foreach ($ltTmp as $ltSpec) {
                    if (($ltSpec->state == "hold") && ($ltSpec->jumlah > 0)) {
                        $byUpdateHold[] = $ltSpec->oleh_id;
                    }
                }
                if (sizeof($byUpdateHold) > 0 && !in_array($this->session->login['id'], $byUpdateHold)) {
                    // sudah ada lock tapi di-lock user lain
                    matiHere("Transaksi tidak dapat dilanjut karena sesi locker sedang dipegang oleh pengguna lain.<br>Silakan berkoordinasi agar tidak terjadi transaksi ganda.");
                }
            }
        }
        // endregion

        echo "<script>top.writeProgress('MEMUAT CONFIG', 'HEAD');</script>";

        $paramPatchers = $this->config->item('heTransaksi_paramPatchers') != null ? $this->config->item('heTransaksi_paramPatchers') : array();
        $paramForceFillers = $this->config->item('heTransaksi_paramForceFillers') != null ? $this->config->item('heTransaksi_paramForceFillers') : array();

        echo "<script>top.writeProgress('MENYIAPKAN CALCULATOR', 'HEAD');</script>";

        $this->load->library("FieldCalculator");
        $cal = new FieldCalculator();

        echo "<script>top.writeProgress('MENYIAPKAN DATA-DATA TRANSAKSI', 'HEAD');</script>";

        //==ambil datanya
        $stepNowParameter = array();
        $this->load->model("MdlTransaksi");
        $tr = new MdlTransaksi();
        $tr->addFilter("id in (" . implode(",", explode("-", $no)) . ")");
        $tr->addFilter("step_number='" . $stepNumCurrent . "'");
        $tr->addFilterJoin("transaksi_data.trash='0'");
        $tmpTr = $tr->lookupJoined();
        //ceklIme($this->db->last_query());

        // 2. Early Validation: Batalkan transaksi jika data tidak ditemukan (misal karena step sudah pindah akibat klik ganda)
        if (sizeof($tmpTr) == 0) {
            die("Transaksi tidak valid atau sudah diproses sebelumnya.");
        }


        if (sizeof($tmpTr) > 0) {
            $this->jenisTr = $tmpTr[0]->jenis_master;

            $cCode = "_TR_" . $this->jenisTr;
            //region session init
            if (!isset($_SESSION[$cCode])) {
                $_SESSION[$cCode] = array(
                    "items" => array(),
                    "main" => array(),
                );
            }
            if (!isset($_SESSION[$cCode]['main'])) {
                $_SESSION[$cCode]['main'] = array();
            }
            if (!isset($_SESSION[$cCode]['items'])) {
                $_SESSION[$cCode]['items'] = array();
            }
            // Sanitasi array items: bersihkan item phantom (tanpa nama/handler valid)
            if (isset($_SESSION[$cCode]['items']) && sizeof($_SESSION[$cCode]['items']) > 0) {
                foreach ($_SESSION[$cCode]['items'] as $kItem => $vItem) {
                    $namaItem = isset($vItem['nama']) ? trim($vItem['nama']) : (isset($vItem['name']) ? trim($vItem['name']) : "");
                    $hasHandler = isset($vItem['handler']) && strlen(trim($vItem['handler'])) > 0;
                    if ($namaItem === "" || (!empty($vItem['projectID']) && isset($vItem['id']) && $vItem['id'] == $vItem['projectID'] && !$hasHandler)) {
                        unset($_SESSION[$cCode]['items'][$kItem]);
                    }
                }
            }
            $_SESSION[$cCode]['rsltItems'] = array();
            $_SESSION[$cCode]['rsltItems2'] = array();
            //endregion

