        $tmpTr = $tr->lookupMainTransaksi()->result();
        //        cekOrange($this->db->last_query());
        $insertID = $tmpTr[0]->id;
        $insertNum = $tmpTr[0]->nomer;
        $masterID = $tmpTr[0]->id_master;
        // endregion transaksi yang dibuka
