            $trr->addFilter("transaksi_id='$no'");
            $tmpReg = $trr->lookupDataRegistries()->result();

            $mainOriginal = array();
            $itemsOriginal = array();
            $main = array();
            $items = array();
            $items2 = array();

            $items3 = array();
            $items4 = array();
            $items5 = array();
            $items7 = array();
            $items_komposisi = array();

            $items2_sum = array();
            $items3_sum = array();
            $rsltItems = array();
            $rsltItems2 = array();
