            $childTableInParams = array();
            $childTableInParamsRsltItems = array();
            $childTableInParamsRsltItems2 = array();
            $masterTableInValueParams = array();
            $childTableInValueParams = array();
            $childTableInValueParamsRsltItems = array();
            $childTableInValueParamsRsltItems2 = array();
            $masterAddValues = array();
            $masterAddFields = array();
            $mainElements = array();
            $mainInputs = array();
            if (sizeof($tmpReg) > 0) {
                foreach ($tmpReg as $row) {
                    foreach ($row as $key_reg => $val_reg) {
                        if ($key_reg != "transaksi_id") {
                            switch ($key_reg) {
                                case "main"://
                                    $main = $main + unserialize(base64_decode($val_reg));
                                    $mainOriginal = $main;
                                    break;
                                case "items"://
                                    $unserItems = @unserialize(base64_decode($val_reg));
                                    if (is_array($unserItems)) {
                                        foreach ($unserItems as $kItem => $vItem) {
                                            $namaItem = isset($vItem['nama']) ? trim($vItem['nama']) : (isset($vItem['name']) ? trim($vItem['name']) : "");
                                            $hasHandler = isset($vItem['handler']) && strlen(trim($vItem['handler'])) > 0;
                                            if ($namaItem === "" || (!empty($vItem['projectID']) && isset($vItem['id']) && $vItem['id'] == $vItem['projectID'] && !$hasHandler)) {
                                                unset($unserItems[$kItem]);
                                            }
                                        }
                                        $items = $items + $unserItems;
                                    }
                                    $itemsOriginal = $items;
                                    break;
                                case "items2"://
                                    $items2 = $items2 + unserialize(base64_decode($val_reg));
                                    break;
                                case "items3"://
                                    $items3 = $items3 + unserialize(base64_decode($val_reg));
                                    break;
                                case "items4"://
                                    $items4 = $items4 + unserialize(base64_decode($val_reg));
