                                    }
                                }
                            }
                        }

                        //update unset yg key nol, karena pada titik ini sudah ada id project sebagai id items 1
                        unset($items[0]);
                    }
                    else {
                        unset($items[$id]);
                        unset($childGates[$id]);
                        unset($childTableInParams[$id]);
                        unset($childTableInValueParams[$id]);

                    }


