    public function showRincian()
    {
//        arrPrint($this->uri->segment_array());
        $modeShow = isset($_GET["mode"]) ? $_GET["mode"] : "nota";
        $this->load->model("Mdls/MdlProdukProject");
        $this->load->model("Mdls/MdlProjectWorkOrder");
        $this->load->model("Mdls/MdlProjectKomposisiWorkorder");
        $trID = $this->uri->segment(5);
        $p = new MdlProdukProject();
        $w = new MdlProjectWorkOrder();
        $k = new MdlProjectKomposisiWorkorder();
        $p->addFilter("transaksi_id='$trID'");
        $tempProduk = $p->lookUpAll()->result();
//        cekLime($this->db->last_query());
//        arrprint($tempProduk);
        $pid = $tempProduk[0]->id;

        $w->addFilter("produk_id='$pid'");
        $tempWo = $w->lookUpAll()->result();
        cekLime($this->db->last_query());
        $womasterData = array();
        foreach ($tempWo as $tempWo_0) {
//            arrPrint($tempWo_0);
            $womasterData[$tempWo_0->id] = $tempWo_0->nama;
        }

        $k->addFilter("produk_id='$pid'");
        $tempKomposisiWo = $k->lookUpKomposisiFase();
        $komposisiHeader = array("jml" => "qty", "nama", "subtotal");
        $detil = array();
        foreach ($tempKomposisiWo as $woID => $woData) {
            if (isset($woData["produk"])) {
                foreach ($woData["produk"] as $produkDatas) {
//                    arrPrint($produkDatas);

//                    $detil[$produkDatas["fase_id"]][$produkDatas["id"]]["harga"]=$produkDatas["harga"];
                    $detil[$produkDatas["fase_id"]][$produkDatas["id"]]["nama"] = $produkDatas["produk_dasar_nama"];
                    $detil[$produkDatas["fase_id"]][$produkDatas["id"]]["jml"] = $produkDatas["jml"];
                    $detil[$produkDatas["fase_id"]][$produkDatas["id"]]["satuan"] = $produkDatas["satuan"];
//                    $detil[$produkDatas["fase_id"]][$produkDatas["id"]]["subtotal"]=$produkDatas["jml"]*$produkDatas["harga"];
                }
            }
        }
//        arrPrint($womasterData);
//        cekLime($this->db->last_query());
//        matiHEre();

//        $tblData = "<div>";
        $tblData = "<table class='table table-responsive table-bordered'>";
        $tblData .= "<tr>";
        $tblData .= "<th>No</th>";
        $tblData .= "<th>Pekerjaan</th>";
        $tblData .= "<th>item</th>";
        $tblData .= "<th>jml</th>";
        $tblData .= "<th>satuan</th>";
        $i = 0;
        foreach ($womasterData as $idWo => $woLabel) {
            $i++;
//            arrprint($woLabel);
            $rowspan = count($detil[$idWo]) + 1;
            $tblData .= "<tr>";
            $tblData .= "<td rowspan='$rowspan'>$i</td>";
            $tblData .= "<td rowspan='$rowspan'>$woLabel</td>";
            $tblData .= "</tr>";

            foreach ($detil[$idWo] as $x => $xData) {
                $tblData .= "<tr>";
                $tblData .= "<td colspan=''>" . $xData["nama"] . "</td>";
                $tblData .= "<td colspan=''>" . $xData["jml"] . "</td>";
                $tblData .= "<td colspan=''>" . $xData["satuan"] . "</td>";
                $tblData .= "</tr>";
            }

//            $tblData .= "</td>";

        }
//        $tblData .="<th>";
        $tblData .= "</tr>";

        $tblData .= "</table>";
//        $tblData .= "</div>";
        if ($modeShow == "show") {
            echo $tblData;
        }
        else {
            return $tblData;
        }

    }

