        $cCode = $this->cCode;

        $arrRetensi = isset($_SESSION[$cCode]['items5']) ? $_SESSION[$cCode]['items5'][0] : array();

        $total_project = $arrRetensi['harga_project'];
        $persen = $arrRetensi['persen'];
        $retensiRp = $arrRetensi['harga'];
        $retensiEndDate = $arrRetensi['tgl_akhir_garansi'];
        $keterangan = $arrRetensi['keterangan_garansi'];

        //=============================SETTING GARANSI/RETENSI====================================
        echo "<form id='table_garansi_form' method='post' name='table_garansi_form' target='result' action='" . MODUL_PATH . "FollowUp/editRetensi/$transaksi_id?debuger=1&project_id=$project_id'>";
        echo "<table id='table_retensi' width='100%' class='table dataTable compact table-bordered table-hover-color-red table-striped'>";
        echo "<caption class='text-red text-bold text-uppercase'><i class='fa fa-info-circle text-info'></i> yang bisa direvisi hanya tanggal berakhir dan keterangan retensi.</caption>";
        echo "<thead>";
        echo "<tr class='bg-gray'>";
        echo "<th>NILAI GARANSI (%) <br>dari TOTAL PROJECT</th>";
        echo "<th>Total (Rp)</th>";
        echo "<th>Tgl Berakhirnya Garansi</th>";
        echo "<th>Keterangan Garansi</th>";
        echo "<th>&nbsp;</th>";
        echo "</tr>";
        echo "</thead>";
        echo "<tbody>";

        echo "<tr>";
        echo "<td><input readonly total_project='$total_project' id='input_garansi' name='garansi' class='form-control text-right' value='$persen'></td>";
        echo "<td><input readonly total_project='$total_project' id='input_total_garansi' name='total_garansi' class='form-control text-right' value='" . number_format($retensiRp) . "'></td>";
        echo "<td><input required id='input_tgl_akhir_garansi' name='tgl_akhir_garansi' class='form-control text-center' type='date' value='$retensiEndDate'></td>";
        echo "<td><textarea required id='input_keterangan_garansi' placeholder='keterangan' name='keterangan_garansi'>$keterangan</textarea></td>";
        echo "<td><button type='submit' id='btn_table_garansi_form' class='btn btn-sm btn-success'><i class='fa fa-save'></i> SIMPAN</button></td>";
        echo "</tr>";

        echo "<script>
                    $('#input_garansi').on('keyup', function(){
                        var total_project = $(this).attr('total_project');
                        var current_value = $(this).val();
                        var total_garansi = total_project*(current_value/100);
                        $('#input_total_garansi').val(addCommas(total_garansi.toFixed(0)));
                    });
                    
                    $('#table_garansi_form').on('submit', function() {
                        $('#modal_loading_overlay').show();
                    });
              </script>";


        echo "</tbody>";
        echo "</table>";
        echo "</form>";

        echo "
        
        <div id='modal_loading_overlay'
             style='
                position:absolute;
                top:0;
                left:0;
                width:100%;
                height:100%;
                background:rgba(0,0,0,0.5);
                display:none;
                z-index:9999;
                text-align:center;
                padding-top:10%;
             '>
             <i class='fa fa-spinner fa-spin fa-3x text-white'></i>
        </div>
        
        
        ";

    }

