        $clean_garansi = preg_replace('/[^0-9.]/', '', $_POST['garansi']);
        $clean_total_garansi = preg_replace('/[^0-9.]/', '', $_POST['total_garansi']);
        $tgl_end = isset($_POST['tgl_akhir_garansi']) && $_POST['tgl_akhir_garansi'] != "" ? trim($_POST['tgl_akhir_garansi']) : "";
        $keterangan = isset($_POST['keterangan_garansi']) && $_POST['keterangan_garansi'] != "" ? trim($_POST['keterangan_garansi']) : "-";

        $trr = new MdlTransaksi();
        $trr->setFilters(array());
        $this->db->select("items5");
        $trr->addFilter("transaksi_id='$target_tr_id'");
        $tmpReg = $trr->lookupDataRegistries()->result();
        $this->db->trans_start();

        $sukses = false;
        $updated = array();
        if (!empty($tmpReg)) {
            foreach ($tmpReg as $row) {
                $dataReg = blobDecode($row->items5);
                if ($tgl_end != "" && $keterangan != "") {
                    $updated[] = array(
                        "harga_project" => $dataReg[0]['harga_project'],
                        "persen" => $dataReg[0]['persen'],
                        "harga" => $dataReg[0]['harga'],
                        "tgl_akhir_garansi" => $tgl_end,
                        "keterangan_garansi" => $keterangan
                    );
                }
            }
            if (!empty($updated)) {
                $dataEnc = $updated;
                $where = array("transaksi_id" => $target_tr_id);
                $trr->setFilters(array());
                $regUpdate = $trr->updateDataRegistry($where, array("items5" => $dataEnc));
                if ($regUpdate) {
                    $sukses = true;
                }
            }
        }

        if ($sukses && $this->db->trans_complete()) {
            echo "<script>
                    top.swal('sukses disimpan','retensi sudah diupdate<br>halaman akan refresh sebentar lagi.','success');
                    top.swal.enableLoading();
                    setTimeout(function(){
                        top.swal.close();
                        top.$('#reloadTasklistModal').trigger('click');
                    }, 2500);
                </script>";
        }
        else {
            echo "<script>
                    top.swal('gagal update','tunggu beberapa saat, lalu ulangi lagi.','warning');
                    top.swal.enableLoading();
                    setTimeout(function(){
                        top.swal.close();
                        top.$('#reloadTasklistModal').trigger('click');
                    }, 2500);
                </script>";
        }

    }

    public function editRetensi()
    {
        $target_tr_id = $this->uri->segment(4);

        $clean_garansi = preg_replace('/[^0-9.]/', '', $_POST['garansi']);
        $clean_total_garansi = preg_replace('/[^0-9.]/', '', $_POST['total_garansi']);
        $project_id = preg_replace('/[^0-9.]/', '', $_GET['project_id']);

        $tgl_end = isset($_POST['tgl_akhir_garansi']) && $_POST['tgl_akhir_garansi'] != "" ? trim($_POST['tgl_akhir_garansi']) : "";
        $keterangan = isset($_POST['keterangan_garansi']) && $_POST['keterangan_garansi'] != "" ? trim($_POST['keterangan_garansi']) : "-";

        $trr = new MdlTransaksi();
        $trr->setFilters(array());
        $this->db->select("items5");
        $trr->addFilter("transaksi_id='$target_tr_id'");
        $tmpReg = $trr->lookupDataRegistries()->result();

        $this->db->trans_start();

        $sukses = false;
        $updated = array();
        $oldAudit = array();
        $newAudit = array();

        if (!empty($tmpReg)) {
            foreach ($tmpReg as $row) {
                $dataReg = blobDecode($row->items5);

                if (!empty($dataReg) && isset($dataReg[0])) {
                    $oldAudit[] = $dataReg[0];

                    $newRow = array(
                        "harga_project"        => isset($dataReg[0]['harga_project']) ? $dataReg[0]['harga_project'] : "",
                        "persen"               => isset($dataReg[0]['persen']) ? $dataReg[0]['persen'] : "",
                        "harga"                => isset($dataReg[0]['harga']) ? $dataReg[0]['harga'] : "",
                        "tgl_akhir_garansi"    => $tgl_end,
                        "keterangan_garansi"   => $keterangan
                    );

                    $updated[] = $newRow;
                    $newAudit[] = $newRow;
                }
            }

            if (!empty($updated)) {
                $dataEnc = $updated;
                $where = array("transaksi_id" => $target_tr_id);

                $trr->setFilters(array());
                $regUpdate = $trr->updateDataRegistry($where, array("items5" => $dataEnc));

                if ($regUpdate) {
                    $sukses = true;

                    // =========================
                    // SIMPAN AUDIT TRAIL
                    // =========================
                    $session_user_id = $this->session->login['id'] ? $this->session->login['id'] : null;
                    $session_username = $this->session->login['nama_login'] ? $this->session->login['nama_login'] : null;

                    $auditData = array(
                        'project_id'   => $project_id,
                        'transaksi_id' => $target_tr_id,
                        'user_id'      => $session_user_id,
                        'username'     => $session_username,
                        'action'       => 'EDIT_RETENSI',
                        'old_value'    => json_encode($oldAudit),
                        'new_value'    => json_encode($newAudit),
                        'keterangan'   => 'Update tanggal akhir garansi / retensi',
                        'ip_address'   => $this->input->ip_address(),
                        'user_agent'   => isset($_SERVER['HTTP_USER_AGENT']) ? $_SERVER['HTTP_USER_AGENT'] : null,
                        'created_at'   => date('Y-m-d H:i:s')
                    );

                    $this->db->insert('project_audit_trail_retensi', $auditData);
                }
            }
        }

        $this->db->trans_complete();

        if ($sukses && $this->db->trans_status() === TRUE) {
            echo "<script>
                top.swal('sukses disimpan','retensi sudah diupdate<br>halaman akan refresh sebentar lagi.','success');
                top.swal.enableLoading();
                setTimeout(function(){
                    top.swal.close();
                    top.$('#reloadTasklistModal').trigger('click');
                }, 2500);
            </script>";
        } else {
            echo "<script>
                top.swal('gagal update','tunggu beberapa saat, lalu ulangi lagi.','warning');
                top.swal.enableLoading();
                setTimeout(function(){
                    top.swal.close();
                    top.$('#reloadTasklistModal').trigger('click');
                }, 2500);
            </script>";
        }
    }

    public function rebuildMainSession()
    {
        $cCode = $this->cCode;

        $sesAwal = array();
        if (isset($_SESSION[$cCode]['items2'][0])) {
            $sesAwal = $_SESSION[$cCode]['items2'][0];
        }

        $hpp_material = 0;
        $hpp_biaya = 0;
        $total_hpp = 0;

        $anggaran_material = 0;
        $anggaran_biaya = 0;
        $total_anggaran = 0;

        // =======================
        // PRODUK (material)
        // HPP        = jml * hpp_supplier
        // Anggaran   = jml * harga
        // =======================
        if (isset($sesAwal['produk']) && is_array($sesAwal['produk'])) {
            foreach ($sesAwal['produk'] as $id => $row) {
                $jml = isset($row['jml']) ? (float)$row['jml'] : 0;
                $hppSupplier = isset($row['hpp_supplier']) ? (float)$row['hpp_supplier'] : 0;
                $harga = isset($row['harga']) ? (float)$row['harga'] : 0;

                $hpp_material += ($jml * $hppSupplier);
                $anggaran_material += ($jml * $harga);
            }
        }

        // =======================
        // BIAYA
        // HPP        = jml * anggaran
        // Anggaran   = jml * harga
        // =======================
        if (isset($sesAwal['biaya']) && is_array($sesAwal['biaya'])) {
            foreach ($sesAwal['biaya'] as $id => $row) {
                $jml = isset($row['jml']) ? (float)$row['jml'] : 0;
                $anggaran = isset($row['anggaran']) ? (float)$row['anggaran'] : 0;
                $harga = isset($row['harga']) ? (float)$row['harga'] : 0;

                $hpp_biaya += ($jml * $anggaran);
                $anggaran_biaya += ($jml * $harga);
            }
        }

        $total_hpp = $hpp_material + $hpp_biaya;
        $total_anggaran = $anggaran_material + $anggaran_biaya;

        //BUILD KE MAIN
        $_SESSION[$cCode]['main']['total_anggaran'] = $total_hpp;

        //jika ada harga project pake hrg jual project klo tidak dari total anggoran produk+biaya
        if (!isset($_SESSION[$cCode]['main']['harga_jual_project'])) {
            $_SESSION[$cCode]['main']['harga_non_ppn'] = $total_anggaran;
            $_SESSION[$cCode]['main']['harga_jual_project'] = $total_anggaran;
            $_SESSION[$cCode]['main']['harga_jual_project_ppn'] = $total_anggaran * 0.11;
            $_SESSION[$cCode]['main']['harga_jual_project_nppn'] = $total_anggaran * 1.11;
        }


        $_SESSION[$cCode]['main']['perkiraan_rl_hpp'] = $_SESSION[$cCode]['main']['harga_jual_project'] - $total_hpp;
        $_SESSION[$cCode]['main']['perkiraan_rl_ang'] = $_SESSION[$cCode]['main']['harga_jual_project'] - $total_anggaran;


//        arrPrint(array(
//            'hpp_material'      => $hpp_material,
//            'hpp_biaya'         => $hpp_biaya,
//            'total_hpp'         => $total_hpp,
//            'anggaran_material' => $anggaran_material,
//            'anggaran_biaya'    => $anggaran_biaya,
//            'total_anggaran'    => $total_anggaran,
//        ));
    }

}
